/**
 * @file dataflow_stream_registry.c
 * @brief Stream Registry Implementation
 *
 * Simple array-based registry for tracking active streams.
 * Uses atomic flags for thread-safe access between sensor_task (reader)
 * and comm_task (writer).
 *
 * @note Auto-generated by CircuitOS DataFlow Engine for MCU: theSpeaker
 */

#include "dataflow_stream_registry.h"
#include "osal/osal_log.h"
#include <string.h>

#if defined(ESP_PLATFORM)
#include "freertos/FreeRTOS.h"
#include "freertos/portmacro.h"
#endif

OSAL_LOG_MODULE_REGISTER(stream_registry);

typedef struct {
    uint16_t frame_id;    /* 0 = unused slot */
    bool     active;
} stream_entry_t;

static stream_entry_t s_streams[DF_STREAM_MAX_ENTRIES];
static uint32_t s_active_count = 0;

/* =========================================================================
 * Internal helpers
 * ========================================================================= */

static int find_slot(uint16_t frame_id) {
    for (int i = 0; i < DF_STREAM_MAX_ENTRIES; i++) {
        if (s_streams[i].frame_id == frame_id) {
            return i;
        }
    }
    return -1;
}

static int find_free_slot(void) {
    for (int i = 0; i < DF_STREAM_MAX_ENTRIES; i++) {
        if (s_streams[i].frame_id == 0) {
            return i;
        }
    }
    return -1;
}

/* =========================================================================
 * Public API
 * ========================================================================= */

void stream_registry_init(void) {
    memset(s_streams, 0, sizeof(s_streams));
    s_active_count = 0;
    OSAL_LOGI("Stream registry initialized (max %d streams)", DF_STREAM_MAX_ENTRIES);
}

void stream_registry_start(uint16_t frame_id) {
    if (frame_id == 0) return;

    int idx = find_slot(frame_id);
    if (idx >= 0) {
        if (!s_streams[idx].active) {
            s_streams[idx].active = true;
            s_active_count++;
            OSAL_LOGI("Stream started: frame_id=0x%04X (active: %lu)",
                      (unsigned)frame_id, (unsigned long)s_active_count);
        }
        return;
    }

    idx = find_free_slot();
    if (idx < 0) {
        OSAL_LOGE("Stream registry full, cannot start frame_id=0x%04X", (unsigned)frame_id);
        return;
    }

    s_streams[idx].frame_id = frame_id;
    s_streams[idx].active = true;
    s_active_count++;
    OSAL_LOGI("Stream registered + started: frame_id=0x%04X slot=%d (active: %lu)",
              (unsigned)frame_id, idx, (unsigned long)s_active_count);
}

void stream_registry_stop(uint16_t frame_id) {
    if (frame_id == 0) return;

    int idx = find_slot(frame_id);
    if (idx >= 0 && s_streams[idx].active) {
        s_streams[idx].active = false;
        if (s_active_count > 0) s_active_count--;
        OSAL_LOGI("Stream stopped: frame_id=0x%04X (active: %lu)",
                  (unsigned)frame_id, (unsigned long)s_active_count);
    }
}

bool stream_registry_is_active(uint16_t frame_id) {
    if (frame_id == 0) return false;

    int idx = find_slot(frame_id);
    return (idx >= 0) && s_streams[idx].active;
}

void stream_registry_stop_all(void) {
    for (int i = 0; i < DF_STREAM_MAX_ENTRIES; i++) {
        s_streams[i].active = false;
    }
    s_active_count = 0;
    OSAL_LOGI("All streams stopped");
}

uint32_t stream_registry_active_count(void) {
    return s_active_count;
}